package org.sonar.linguist;

import java.nio.charset.StandardCharsets;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import static org.assertj.core.api.Assertions.assertThat;

class GeneratedDetectorTest {
  @ParameterizedTest
  @MethodSource("generatedPaths")
  void detectsGeneratedPaths(String path) {
    assertThat(detect(path, "")).isTrue();
  }

  @ParameterizedTest
  @MethodSource("generatedContents")
  void detectsGeneratedContent(String path, String content) {
    assertThat(detect(path, content)).isTrue();
  }

  @Test
  void rejectsOrdinaryFiles() {
    assertThat(detect("src/Main.java", "class Main {}\n")).isFalse();
    assertThat(detect("vendor/candy/food.go", "package food\n")).isFalse();
    assertThat(detect("vendor/-github.com/example/library.go", "package library\n")).isFalse();
    assertThat(detect("vendor/github-.com/example/library.go", "package library\n")).isFalse();
    assertThat(detect("app.js", "const value = 1;\n")).isFalse();
    assertThat(detect("index.html", "<html>\n<meta name=\"generator\" content=\"hand-written\">\n</html>\n")).isFalse();
  }

  @Test
  void handlesLongGoVendorDomainsWithoutExhaustingTheStack() {
    String domain = "a.".repeat(10_000) + "com";
    assertThat(detect("vendor/" + domain + "/library.go", "package library\n")).isTrue();
  }

  @Test
  void detectsPegParserWhenTheMarkerFollowsALongPrefix() {
    String prefix = "a".repeat(50_000);
    assertThat(detect("parser.js", prefix + "/* Generated by PEG.js 0.10 */\n" + "x\n".repeat(1_000))).isTrue();
  }

  @Test
  void handlesLongFirstLinesWithoutExhaustingTheStack() {
    String longFirstLine = "a".repeat(50_000);
    assertThat(detect("bundle.js", longFirstLine + "\n" + "x\n".repeat(1_000))).isFalse();
  }

  @Test
  void ignoresPegMarkerOutsideTheFirstBlockComment() {
    assertThat(detect("parser.js", "/* banner */\nvar Generated by PEG.js;\n")).isFalse();
  }

  private static Stream<String> generatedPaths() {
    return Stream.of(
      "project.xcuserstate",
      ".idea/workspace.xml",
      "Pods/library/source.m",
      "Carthage/Build/library.framework",
      "src/__generated__/query.graphql.js",
      "Form.designer.cs",
      "login.feature.cs",
      "composer.lock",
      "Cargo.lock",
      "Cargo.toml.orig",
      "deno.lock",
      "flake.lock",
      "MODULE.bazel.lock",
      "node_modules/package/index.js",
      "vendor/github.com/example/library.go",
      "Gopkg.lock",
      "Package.resolved",
      "poetry.lock",
      "pdm.lock",
      "uv.lock",
      "pixi.lock",
      "project.esy.lock",
      "npm-shrinkwrap.json",
      "package-lock.json",
      "pnpm-lock.yaml",
      "bun.lockb",
      ".terraform.lock.hcl",
      ".pnp.cjs",
      "Godeps/Godeps.json",
      "source.zep.c",
      "htmlcov/index.html",
      "Pipfile.lock",
      "gradlew.bat",
      "mvnw.cmd",
      "mise.linux.lock",
      ".secrets.baseline",
      "JuliaManifest-v1.11.toml",
      "generated_tlb.pas",
      ".sqlx/query-2b8b1aae3740a05cb7179be9c7d5af30e8362c3cba0b07bc18fa32ff1a2232cc.json",
      "app.js.map");
  }

  private static Stream<Arguments> generatedContents() {
    return Stream.of(
      arguments("app.js", "x".repeat(111)),
      arguments("app.css", "body {}\n/*# sourceMappingURL=app.css.map */"),
      arguments("app.js", "const value = 1;\nsourceURL=app.js\n"),
      arguments("custom.map", "{\"version\":3,\"sources\":[]}"),
      arguments("coffee.js", "// Generated by CoffeeScript 2.7\n"),
      arguments("parser.js", "/* Generated by PEG.js 0.10 */\n"),
      arguments("assembly.xml", "<?xml version=\"1.0\"?>\n<doc>\n<assembly>\n</assembly>\n</doc>\n"),
      arguments("drawing.ps", "%!PS\n%%Creator: Inkscape 1.3\n"),
      arguments("module.c", "/* Generated by Cython 3.0 */\nint value;\n"),
      arguments("api.go", "package api\n// Code generated by tool\n"),
      arguments("api.proto", "syntax = \"proto3\";\n// This file was autogenerated by go-to-protobuf\n"),
      arguments("api.pb.java", "// Generated by the protocol buffer compiler.  DO NOT EDIT!\nclass Api {}\n"),
      arguments("proto.js", "0\n1\n2\n3\n4\n// GENERATED CODE -- DO NOT EDIT!\n6\n"),
      arguments("proto.ts", "// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n1\n2\n3\n4\n"),
      arguments("service.rb", "# Code generated by protoc-gen-twirp_ruby 1.14.1, DO NOT EDIT.\nclass Service\n"),
      arguments("service.py", "# Autogenerated by Thrift Compiler\nclass Service:\n"),
      arguments("jni.h", "/* DO NOT EDIT THIS FILE - it is machine generated */\n#include <jni.h>\nvoid call();\n"),
      arguments("cassette.yml", "---\nrecorded_with: VCR\n"),
      arguments("grammar.g", "grammar Example;\n// generated by Xtest\nrule: VALUE;\n"),
      arguments("board.mod", "PCBNEW-LibModule-V1 2026-01-01\n$INDEX\n"),
      arguments("asset.meta", "fileFormatVersion: 2\nguid: abc\n"),
      arguments("parser.rb", "first\nsecond\n# This file is automatically generated by Racc 1.8\n"),
      arguments("Lexer.java", "/* The following code was generated by JFlex 1.9 */\nclass Lexer {}\n"),
      arguments("Parser.java", "// This is a generated file. Not intended for manual editing.\nclass Parser {}\n"),
      arguments("topic.Rd", "% Generated by roxygen2: do not edit by hand\n\\name{topic}\n"),
      arguments("parser.js", "/* parser generated by jison 0.4 */\nvar parser;\n"),
      arguments("service.grpc.pb.cc", "// Generated by the gRPC C++ plugin.\nvoid call();\n"),
      arguments("model.dart", "// GENERATED CODE - DO NOT MODIFY\nclass Model {}\n"),
      arguments("ppport.h", "0\n1\n2\n3\n4\n5\n6\n7\nAutomatically created by Devel::PPPort\n9\n10\n"),
      arguments("project.yy", "{\n  resourceType: object\n}\nend\n"),
      arguments("image.c", "/* GIMP RGB C-Source image dump (image.c) */\n"),
      arguments("image.h", "/*  GIMP header image file format (RGB): image.h  */\n"),
      arguments("project.dsp", "# Microsoft Developer Studio Generated Build File\n"),
      arguments("app.lua", "-- Generated by Haxe\nprint('hello')\n"),
      arguments("index.html", "<html>\n<meta name=\"generator\" content=\"org mode\">\n</html>\n"),
      arguments("Tables.java", "// This file is generated by jOOQ.\nclass Tables {}\n"),
      arguments("types.rbi",
        "# typed: true\n# frozen\n# DO NOT EDIT MANUALLY\n# generated\n# Please run `bin/tapioca dsl`\n"),
      arguments("view.frm", "TYPE=VIEW\nquery=select 1\n"));
  }

  private static Arguments arguments(String path, String content) {
    return Arguments.of(path, content);
  }

  private static boolean detect(String path, String content) {
    return GeneratedDetector.detect(FileContent.copyOf(path, content.getBytes(StandardCharsets.UTF_8)));
  }
}
